"""Sync canonicalization grid: every declared (channels, width, rate, frames) shape.

``canonical_pcm`` is the shared strict reader for decoded sync WAL uploads and
held WAVs. This grid pins its full verdict surface for rates 21000..48001:

- every declared shape outside the admissible envelope (1-2 channels, PCM
  width 1-4, 8-48 kHz) is refused with the typed deterministic fault
  ``StagedAudioInvalid`` -- a ``ValueError`` subclass, so every legacy
  ``except ValueError`` caller keeps catching it;
- a container wave itself refuses to open (0 channels / 0 sample width) is
  the container fault, not the shape fault;
- every admissible shape canonicalizes to the exact documented pipeline
  output (bias width-1 to signed, widen to PCM16, fold stereo to mono,
  resample to 16 kHz), frozen here as verified literals.

A cell that fails means the reader drifted from the documented pipeline.

Failure-Class: FC-sync-decode-fault-anonymous-at-typed-boundaries
"""

import struct
import wave

import pytest

from utils.batch_pipeline.audio import StagedAudioInvalid
from utils.batch_pipeline.capture_decode import canonical_pcm

_PATTERN = b'\x0a\x1c\x2e\x3f'


def _payload(frames: int, channels: int, width: int) -> bytes:
    n = frames * channels * width
    return (_PATTERN * (n // 4 + 2))[:n]


def _wav_bytes(channels: int, width: int, rate: int, frames: int) -> bytes:
    payload = _payload(frames, channels, width)
    if channels >= 1 and 1 <= width <= 4:
        out = __import__('io').BytesIO()
        with wave.open(out, 'wb') as stream:
            stream.setnchannels(channels)
            stream.setsampwidth(width)
            stream.setframerate(rate)
            stream.writeframes(payload)
        return out.getvalue()
    data_size = len(payload) + (len(payload) % 2)
    header = b'RIFF' + struct.pack('<I', 36 + data_size) + b'WAVE'
    header += b'fmt ' + struct.pack(
        '<IHHIIHH', 16, 1, channels, rate, rate * channels * width, channels * width, width * 8
    )
    header += b'data' + struct.pack('<I', data_size)
    return header + payload


@pytest.fixture(scope='module')
def grid_root(tmp_path_factory):
    return tmp_path_factory.mktemp('sync_canonical_grid')


def test_canonical_ch0_w0_r21000_f0(grid_root) -> None:
    """channels=0, width=0, rate=21000, frames=0: container."""
    path = grid_root / "ch0_w0_r21000_f0.wav"
    path.write_bytes(_wav_bytes(0, 0, 21000, 0))
    with pytest.raises(StagedAudioInvalid) as caught:
        canonical_pcm(str(path))
    assert type(caught.value) is StagedAudioInvalid
    assert str(caught.value) == 'invalid sync audio container'
    assert isinstance(caught.value, ValueError)


